#!/usr/bin/env python3
"""v1.6.72 : Ergonomie et lisibilité des comparaisons de profils."""
from pathlib import Path
page=Path('android/source-1.6.72/app/src/main/assets/index.html')
source=page.read_text(encoding='utf-8')
a=source.index(" function compareTarget(target){")
b=source.index(" function redraw(friendArea){",a)
assert b>a and b-a<6000, "Section de comparaison absente ou modifiée"
source=source[:a]+" let comparisonPeriod='month',comparisonZoom='local',comparisonPinch=1;\n function compareTarget(target){\n  target.append(sectionTitle('Comparer les profils'));\n  target.append(node('p','advanced-help','Chaque personne commence au jour 0 de son propre suivi. Les périodes courtes permettent de voir les premières semaines de chacun.'));\n  const people=[...(data.profiles||[]).map(p=>({id:'local:'+p.id,name:p.name,local:true})),\n   ...getReceivedList().map(p=>({id:'received:'+p.key,name:p.name,local:false}))];\n  const opts=node('div','compare-profile-list');\n  for(const item of people){\n   if(item.id===unifiedCurrent)continue;\n   opts.append(checkbox(item.name+(item.local?' · Personnel':' · Partagé'),sharedWanted.has(item.id),checked=>{\n    if(checked){\n     sharedWanted.add(item.id);\n     if(!item.local&&!sharedMap.has(item.id.slice(9)))window.AndroidBackup?.loadComparisonProfile?.(item.id.slice(9));\n    }else sharedWanted.delete(item.id);\n    comparisonPinch=1;redraw();\n   }));\n  }\n  target.append(opts);\n  const refresh=button('↻ Actualiser les profils partagés',false,()=>{\n   const selected=[...sharedWanted].filter(id=>id.startsWith('received:'));\n   if(!selected.length){sharedState='Sélectionne un profil partagé pour l’actualiser.';redraw();return}\n   sharedState='Actualisation des profils choisis…';\n   for(const id of selected)window.AndroidBackup?.loadComparisonProfile?.(id.slice(9));\n   redraw();\n  });\n  refresh.className='secondary compare-refresh';\n  target.append(refresh);\n  if(sharedState)target.append(node('p','advanced-help compare-sync-status',sharedState));\n  const modes=controls(target,[\n   ['Poids réel',metric==='weight',()=>{metric='weight';redraw()}],\n   ['Kg perdus',metric==='loss',()=>{metric='loss';redraw()}],\n   ['% du poids initial',metric==='initial',()=>{metric='initial';redraw()}],\n   ['% de l’objectif',metric==='goal',()=>{metric='goal';redraw()}]\n  ]);\n  modes.classList.add('compare-metric-grid');\n  const selected=[{id:unifiedCurrent,p:current()}];\n  for(const id of sharedWanted){\n   if(id.startsWith('local:'))selected.push({id,p:clean((data.profiles||[]).find(p=>'local:'+p.id===id))});\n   else selected.push({id,p:clean(sharedMap.get(id.slice(9)))});\n  }\n  const series=[];let idx=0;\n  for(const {p} of selected){\n   if(!validComparison(p))continue;\n   const first=p.rows[0],goalRange=first.weight-p.goal;\n   if(metric==='goal'&&goalRange<=0)continue;\n   const points=p.rows.map(r=>{\n    let y=r.weight;\n    if(metric==='loss')y=first.weight-r.weight;\n    else if(metric==='initial')y=100*(first.weight-r.weight)/first.weight;\n    else if(metric==='goal')y=100*(first.weight-r.weight)/goalRange;\n    return {x:days(first.date,r.date),y,date:r.date,weight:r.weight};\n   }).filter(q=>Number.isFinite(q.y)&&Number.isFinite(q.x));\n   if(points.length)series.push({label:p.name,color:colors[idx%colors.length],points});\n   idx++;\n  }\n  if(!series.length){\n   target.append(node('p','advanced-help','Aucune courbe comparable disponible. Vérifie les profils sélectionnés et leurs pesées.'));\n   return;\n  }\n  const maxDay=Math.max(0,...series.map(s=>s.points.at(-1).x));\n  const choices=[['month','Mois',30],...(maxDay>=90?[['three','3 mois',90]]:[]),\n   ...(maxDay>=180?[['six','6 mois',180]]:[]),\n   ...(maxDay>=365?[['year','1 an',365]]:[]),['all','Tout',Infinity]];\n  if(!choices.some(p=>p[0]===comparisonPeriod))comparisonPeriod='month';\n  const periodRow=node('div','compare-period-heading');\n  const periodTitle=node('h3','','Évolution comparée');\n  const periodBtn=button(choices.find(p=>p[0]===comparisonPeriod)[1]+' ↻',false,()=>{\n   const i=choices.findIndex(p=>p[0]===comparisonPeriod);\n   comparisonPeriod=choices[(i+1)%choices.length][0];comparisonPinch=1;redraw();\n  });\n  periodBtn.className='secondary compare-period-button';\n  periodBtn.setAttribute('aria-label','Changer la période de comparaison. Appuyer plusieurs fois pour faire défiler les périodes.');\n  periodRow.append(periodTitle,periodBtn);target.append(periodRow);\n  const zoomRow=node('div','compare-zoom-row');\n  const local=button('Zoom mesures',comparisonZoom==='local',()=>{\n   comparisonZoom='local';redraw();\n  });\n  const global=button('Échelle complète',comparisonZoom==='global',()=>{\n   comparisonZoom='global';redraw();\n  });\n  zoomRow.append(local,global);target.append(zoomRow);\n  const periodMax=choices.find(p=>p[0]===comparisonPeriod)[2];\n  const maxX=Math.max(1,Math.min(maxDay||7,periodMax));\n  const periodEnd=comparisonPeriod==='all'?Math.max(1,maxDay):Math.max(7,maxX);\n  const zoomFactor=Math.max(1,Math.min(6,comparisonPinch));\n  const chartEnd=zoomFactor>1.02?Math.min(periodEnd,maxX):periodEnd;\n  const chartStart=zoomFactor>1.02?Math.max(0,chartEnd-periodEnd/zoomFactor):0;\n  const visible=series.map(s=>({\n   ...s,points:s.points.filter(p=>p.x>=chartStart&&p.x<=chartEnd)\n  })).filter(s=>s.points.length);\n  // Un profil ayant moins de jours de suivi reste affiché sans inventer ses mesures futures.\n  const visibleValues=visible.flatMap(s=>s.points.map(p=>p.y));\n  const allValues=series.flatMap(s=>s.points.map(p=>p.y));\n  let low=Math.min(...(comparisonZoom==='local'&&visibleValues.length?visibleValues:allValues));\n  let high=Math.max(...(comparisonZoom==='local'&&visibleValues.length?visibleValues:allValues));\n  if(comparisonZoom==='global'&&metric!=='weight'){low=Math.min(0,low);high=Math.max(0,high)}\n  if(high-low<.15){const mid=(low+high)/2;low=mid-.5;high=mid+.5}\n  const margin=(high-low)*.1;low-=margin;high+=margin;\n  const w=360,h=300,l=48,r=13,t=17,b=44;\n  const X=v=>l+(v-chartStart)/Math.max(1,chartEnd-chartStart)*(w-l-r);\n  const Y=v=>h-b-(v-low)/(high-low)*(h-t-b);\n  const graphSvg=svg('svg',{viewBox:'0 0 360 300',class:'compare-svg',role:'img',\n   'aria-label':'Comparaison de '+series.length+' profils depuis le premier jour de suivi'},target);\n  const clipId='compare-clip-'+(++graphPlotSerial);\n  const defs=svg('defs',{},graphSvg),clip=svg('clipPath',{id:clipId},defs);\n  svg('rect',{x:l,y:t,width:w-l-r,height:h-t-b},clip);\n  for(let i=0;i<=4;i++){\n   const v=low+(high-low)*i/4,y=Y(v);\n   svg('line',{x1:l,x2:w-r,y1:y,y2:y,stroke:'#3a596d','stroke-width':1},graphSvg);\n   svg('text',{x:l-7,y:y+4,'text-anchor':'end','font-size':14,fill:'#c8dfea'},graphSvg,fmt1(v));\n  }\n  for(let i=0;i<=4;i++){\n   const v=chartStart+(chartEnd-chartStart)*i/4,x=X(v);\n   svg('text',{x,y:h-17,'text-anchor':'middle','font-size':13,fill:'#c8dfea'},graphSvg,Math.round(v)+' j');\n  }\n  const curves=svg('g',{'clip-path':'url(#'+clipId+')'},graphSvg);\n  const detail=node('p','compare-point-detail','Touche un point pour consulter sa valeur exacte.');\n  detail.setAttribute('role','status');\n  detail.setAttribute('aria-live','polite');\n  for(const s of visible){\n   const points=s.points;\n   if(points.length>1)svg('polyline',{\n    points:points.map(p=>X(p.x)+','+Y(p.y)).join(' '),fill:'none',stroke:s.color,\n    'stroke-width':3.4,'stroke-linecap':'round','stroke-linejoin':'round'\n   },curves);\n   const stride=Math.max(1,Math.ceil(points.length/150));\n   for(let i=0;i<points.length;i+=stride){\n    const p=points[i],cx=X(p.x),cy=Y(p.y);\n    svg('circle',{cx,cy,r:3.7,fill:s.color,stroke:'#102b3e','stroke-width':1.1},curves);\n    const hit=svg('circle',{cx,cy,r:13,fill:'transparent',tabindex:0,role:'button',\n     'aria-label':'Afficher '+s.label+' jour '+Math.round(p.x)},curves);\n    const show=()=>{\n     const unit=metric==='weight'||metric==='loss'?' kg':' %';\n     detail.textContent=s.label+' · Jour '+Math.round(p.x)+' · '+fmt1(p.y)+unit\n      +' · Pesée du '+new Date(utc(p.date)).toLocaleDateString('fr-FR');\n    };\n    hit.addEventListener('click',show);\n    hit.addEventListener('keydown',e=>{\n     if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}\n    });\n    hit.style.cursor='pointer';\n   }\n  }\n  const legend=node('div','compare-legend');\n  for(const s of series){\n   const item=node('span','compare-legend-item');\n   const mark=node('span','compare-legend-dot');\n   mark.style.background=s.color;\n   const last=s.points.at(-1);\n   item.append(mark,node('span','',s.label+' · '+Math.round(last.x)+' j'));\n   legend.append(item);\n  }\n  target.append(legend,detail);\n  const note=node('p','advanced-help compare-notice',\n   'Les profils sont alignés au jour 0, mais leurs durées peuvent être différentes. '+ \n   (comparisonPeriod==='all'?'Toutes les données disponibles sont affichées.':'Seuls les jours de la période choisie sont affichés.')+\n   ' Écarte deux doigts sur la courbe pour zoomer et rapproche-les pour réduire.');\n  target.append(note);\n  graphSvg.style.touchAction='pan-y';\n  let initDist=0,originalZoom=1,nextZoom=1;\n  const dist=touches=>Math.hypot(touches[0].clientX-touches[1].clientX,\n   touches[0].clientY-touches[1].clientY);\n  graphSvg.addEventListener('touchstart',e=>{\n   if(e.touches.length!==2)return;\n   initDist=Math.max(10,dist(e.touches));originalZoom=comparisonPinch;nextZoom=originalZoom;\n   if(e.cancelable)e.preventDefault();\n  },{passive:false});\n  graphSvg.addEventListener('touchmove',e=>{\n   if(!initDist||e.touches.length!==2)return;\n   nextZoom=Math.max(1,Math.min(6,originalZoom*dist(e.touches)/initDist));\n   if(e.cancelable)e.preventDefault();\n  },{passive:false});\n  const endTouch=e=>{\n   if(!initDist||(e.touches&&e.touches.length>=2))return;\n   initDist=0;\n   if(Math.abs(nextZoom-comparisonPinch)>.07){\n    comparisonPinch=nextZoom;redraw();\n   }\n  };\n  graphSvg.addEventListener('touchend',endTouch,{passive:true});\n  graphSvg.addEventListener('touchcancel',endTouch,{passive:true});\n  if(comparisonPinch>1.05){\n   const reset=button('Réinitialiser le zoom',false,()=>{\n    comparisonPinch=1;redraw();\n   });\n   reset.className='secondary compare-reset-zoom';target.append(reset);\n  }\n  target.append(node('p','advanced-help compare-readonly',\n   'Les profils partagés restent en lecture seule. Aucune donnée n’est copiée dans ton profil.'));\n }\n"+source[b:]
assert source.count('</head>')==1
source=source.replace('</head>',"<style>\n/* Comparaison : contrôles uniformes, graphique lisible et zoom tactile. */\n.compare-profile-list{margin:12px 0 8px}\n.compare-profile-list .advanced-check{font-size:14px;line-height:1.4}\n.compare-refresh{width:100%;font-size:14px;margin:5px 0 8px;min-height:42px}\n.compare-sync-status{margin:5px 0 10px}\n.advanced-controls.compare-metric-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:8px!important;margin:17px 0 18px!important}\n.compare-metric-grid button{width:100%!important;min-width:0!important;min-height:52px!important;line-height:1.25!important;font-size:clamp(13px,3.65vw,16px)!important;font-weight:650!important;white-space:normal!important;padding:9px 6px!important}\n.compare-period-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:18px 0 10px}\n.compare-period-heading h3{margin:0!important;font-size:17px}\n.compare-period-heading .compare-period-button{flex:0 0 auto;min-width:92px;min-height:45px;padding:10px 12px;font-size:15px;font-weight:700}\n.compare-zoom-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:0 0 13px}\n.compare-zoom-row button{min-width:0;width:100%;min-height:47px;border:1px solid #52758c;background:#234157;color:#f1fbff;border-radius:12px;font:650 clamp(12px,3.5vw,15px) system-ui;padding:9px 6px}\n.compare-zoom-row button.chosen{background:#2b7770;border-color:#89e7d5}\n.compare-svg{display:block;width:100%;height:auto;min-height:0!important;margin:9px 0 6px;overflow:visible}\n.compare-legend{display:flex;flex-wrap:wrap;gap:9px 14px;margin:10px 0;color:#d4e7f1;font-size:13px}\n.compare-legend-item{display:inline-flex;align-items:center;gap:6px;min-width:0;max-width:100%;overflow-wrap:anywhere}\n.compare-legend-dot{width:10px;height:10px;border-radius:50%;display:inline-block;flex:0 0 10px}\n.compare-point-detail{font-size:13px;line-height:1.5;color:#e0f3f9;margin:10px 0;padding:10px;border:1px solid #38586e;border-radius:10px;background:#0e293e}\n.compare-notice{margin-top:13px}\n.compare-readonly{border-top:1px solid #35586d;padding-top:11px;margin-top:13px}\n.compare-reset-zoom{width:100%;font-size:13px;margin-top:6px}\n</style>"+'</head>',1)
for token in ['compare-metric-grid','comparisonPeriod','compare-zoom-row','compare-svg',
              'compare-legend','Réinitialiser le zoom','comparisonPinch']:
 assert token in source, token
assert source.count(' function compareTarget(target){')==1
assert "graph(target,series,{title:'Comparaison des profils" not in source
page.write_text(source,encoding='utf-8')
print('OK v1.6.72 : 2x2 catégories, période cyclique, zoom tactile, points cliquables et échelle lisible')
